import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 1000000000;
    static final int MAXN = 11;
    static final int MAXNODES = 205;
    static final int DIRECTIONS = 4;
    static final int[] dy = {-1, 0, 1, 0};
    static final int[] dx = {0, -1, 0, 1};

    static int n, t;
    static char[][] a = new char[MAXN][MAXN];
    static char[][] b = new char[MAXN][MAXN];
    static int br, bc;
    static int[][] bum = new int[MAXN][MAXN];
    static int[][] dist = new int[MAXN][MAXN];
    static boolean[][] pos = new boolean[MAXN][MAXN];
    static int N;
    static int[][] R = new int[MAXN][MAXN];
    static List<Integer>[] neighbors = new ArrayList[MAXN * MAXN];
    static int[] F = new int[MAXN * MAXN];
    static int[] P = new int[MAXN * MAXN];
    static int total_flow;

    public static void main(String[] args) throws IOException {
        BufferedReader brInput = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(brInput.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXN * MAXN; i++) {
            neighbors[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            String line = brInput.readLine();
            for (int j = 0; j < n; j++) {
                a[i][j] = line.charAt(j);
                if (a[i][j] == 'Z') {
                    br = i;
                    bc = j;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            String line = brInput.readLine();
            for (int j = 0; j < n; j++) {
                b[i][j] = line.charAt(j);
            }
        }

        BFS1();

        N = 2 * n * n + 2;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(a[i][j]) && a[i][j] > '0') {
                    int v = i * n + j + 1;
                    R[0][v] = a[i][j] - '0';
                    neighbors[0].add(v);
                    neighbors[v].add(0);
                    BFS2(i, j);
                    for (int i2 = 0; i2 < n; i2++) {
                        for (int j2 = 0; j2 < n; j2++) {
                            if (pos[i2][j2] && Character.isDigit(b[i2][j2]) && b[i2][j2] > '0') {
                                int u = n * n + i2 * n + j2 + 1;
                                R[v][u] = INF;
                                neighbors[v].add(u);
                                neighbors[u].add(v);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(b[i][j]) && b[i][j] > '0') {
                    int u = n * n + i * n + j + 1;
                    R[u][N - 1] = b[i][j] - '0';
                    neighbors[u].add(N - 1);
                    neighbors[N - 1].add(u);
                }
            }
        }

        int flow;
        total_flow = 0;
        while ((flow = computeFlow()) != 0) {
            total_flow += flow;
        }

        System.out.println(total_flow);
    }

    static void BFS1() {
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(bum[i], t);
        }
        bum[br][bc] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{br, bc});
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int d = bum[v[0]][v[1]];
            for (int i = 0; i < DIRECTIONS; i++) {
                int u0 = v[0] + dy[i];
                int u1 = v[1] + dx[i];
                if (0 <= u0 && u0 < n && 0 <= u1 && u1 < n && a[u0][u1] != 'Y' && d + 1 < bum[u0][u1]) {
                    bum[u0][u1] = d + 1;
                    q.offer(new int[]{u0, u1});
                }
            }
        }
    }

    static void BFS2(int sr, int sc) {
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(dist[i], INF);
        }
        dist[sr][sc] = 0;
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(pos[i], false);
        }
        pos[sr][sc] = true;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc});
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int d = dist[v[0]][v[1]];
            pos[v[0]][v[1]] = d <= bum[v[0]][v[1]];
            if (d >= bum[v[0]][v[1]]) continue;
            for (int i = 0; i < DIRECTIONS; i++) {
                int u0 = v[0] + dy[i];
                int u1 = v[1] + dx[i];
                if (0 <= u0 && u0 < n && 0 <= u1 && u1 < n && a[u0][u1] != 'Y' && d + 1 < dist[u0][u1]) {
                    dist[u0][u1] = d + 1;
                    q.offer(new int[]{u0, u1});
                }
            }
        }
    }

    static int computeFlow() {
        Arrays.fill(F, 0);
        F[0] = INF;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        pq.offer(new int[]{F[0], 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int v = top[1];
            int f = top[0];
            if (F[v] != f) continue;
            for (int u : neighbors[v]) {
                int minF = Math.min(f, R[v][u]);
                if (minF > F[u]) {
                    F[u] = minF;
                    P[u] = v;
                    pq.offer(new int[]{F[u], u});
                }
            }
        }
        int v = N - 1;
        if (F[v] == 0) return 0;
        int flow = F[v];
        while (v != 0) {
            int u = P[v];
            R[u][v] -= flow;
            R[v][u] += flow;
            v = u;
        }
        return flow;
    }
}
